import { test, expect } from "./fixtures";
import type { Locator, Page } from "@playwright/test";
import { BASE_URL } from "./base-url";
import { demoFrame } from "./demo-frame";
import { gotoHydrated } from "./hydration";

// DataTable's Grid layout (backlog row 342), on the `large` demo: 50,000 orders (id, customer, status, total)
// through VirtualGrid with a checkbox column (0), then Order (1), Customer (2), Status (3) and Total (4).
// The data is generated by preview/src/components/data_table/variants/large/mod.rs; the expectations below
// recompute it from the same formulas, so a changed fixture fails here rather than passing by accident.

const PAGE_URL = `${BASE_URL}/component/data_table/`;
const ROWS = 50_000;

/** `total_cents` of order `i` (0-based): `((i + 1) * 2654435761 mod 2^64) mod 100000`. */
const totalCents = (i: number) => Number((BigInt(i + 1) * 2654435761n) % 2n ** 64n % 100000n);
const money = (cents: number) => `$${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, "0")}`;
const STATUS = ["Paid", "Pending", "Failed", "Refunded"];
const status = (i: number) => STATUS[(i * 31) % 4];
const orderId = (i: number) => `ORD-${String(i + 1).padStart(5, "0")}`;

const grid = (page: Page) => demoFrame(page, "large").getByRole("grid");
const cell = (g: Locator, row: number | "header", column: number) => g.locator(`[data-grid-cell="${row}:${column}"]`);
const checkboxIn = (g: Locator, row: number) => cell(g, row, 0).getByRole("checkbox");
const sortButton = (g: Locator, column: number) => cell(g, "header", column).getByRole("button");
const summary = (page: Page) => demoFrame(page, "large").locator('[data-slot="data-table-summary"]');
const filter = (page: Page) => demoFrame(page, "large").getByRole("textbox");
const rowCheckbox = (g: Locator, id: string) => g.getByRole("checkbox", { name: `Select row ${id}`, exact: true });
const scrollTo = (g: Locator, top: number | "end") =>
  g.evaluate((el, to) => {
    el.scrollTop = to === "end" ? el.scrollHeight : to;
  }, top);

test.describe("DataTable Grid layout", () => {
  test("50,000 rows are one scroll canvas with a window of them mounted, sorted by id", async ({ page }) => {
    await gotoHydrated(page, PAGE_URL);
    const g = grid(page);
    await expect(cell(g, 0, 1)).toHaveText("ORD-00001");
    await expect(g).toHaveAttribute("aria-rowcount", String(ROWS + 1));
    expect(await g.locator('[role="row"]:not([data-grid-header])').count()).toBeLessThan(60);
    await expect(cell(g, "header", 1)).toHaveAttribute("aria-sort", "ascending");
    await expect(g.locator('[role="columnheader"][aria-sort]')).toHaveCount(1);
    await expect(summary(page)).toHaveText(`0 of ${ROWS} row(s) selected.`);
  });

  test("sorting a header reorders every row: Total ascending starts at the smallest total", async ({ page }) => {
    await gotoHydrated(page, PAGE_URL);
    const g = grid(page);
    await expect(cell(g, 0, 1)).toHaveText("ORD-00001");
    const totals = Array.from({ length: ROWS }, (_, i) => totalCents(i));
    const min = Math.min(...totals);
    const max = Math.max(...totals);

    await sortButton(g, 4).click();
    await expect(cell(g, "header", 4)).toHaveAttribute("aria-sort", "ascending");
    await expect(cell(g, "header", 1)).not.toHaveAttribute("aria-sort");
    await expect(cell(g, 0, 4)).toHaveText(money(min));

    await sortButton(g, 4).click();
    await expect(cell(g, "header", 4)).toHaveAttribute("aria-sort", "descending");
    await expect(cell(g, 0, 4)).toHaveText(money(max));
  });

  test("the filter narrows the rows and the canvas; clearing it brings them back", async ({ page }) => {
    await gotoHydrated(page, PAGE_URL);
    const g = grid(page);
    await expect(cell(g, 0, 1)).toHaveText("ORD-00001");
    const refunded = Array.from({ length: ROWS }, (_, i) => i).filter((i) => status(i) === "Refunded");

    await filter(page).fill("refunded");
    await expect(g).toHaveAttribute("aria-rowcount", String(refunded.length + 1));
    await expect(summary(page)).toHaveText(`0 of ${refunded.length} row(s) selected.`);
    // Sorted by id ascending, so the first row is the first refunded order.
    await expect(cell(g, 0, 1)).toHaveText(orderId(refunded[0]));
    await expect(cell(g, 0, 3)).toHaveText("Refunded");

    await filter(page).fill("no-such-customer");
    await expect(g).toHaveAttribute("aria-rowcount", "1");
    await expect(demoFrame(page, "large").getByText("No results.")).toBeVisible();

    await filter(page).fill("");
    await expect(g).toHaveAttribute("aria-rowcount", String(ROWS + 1));
  });

  test("a selected row stays selected when it scrolls out of the window and back, and through a sort", async ({ page }) => {
    await gotoHydrated(page, PAGE_URL);
    const g = grid(page);
    await expect(cell(g, 0, 1)).toHaveText("ORD-00001");
    await rowCheckbox(g, "ORD-00001").click();
    await expect(summary(page)).toHaveText(`1 of ${ROWS} row(s) selected.`);
    await expect(g.locator('[role="row"][aria-rowindex="2"]')).toHaveAttribute("aria-selected", "true");

    // Out of the window: the row is not mounted, the selection is still counted. (The grid keeps its active
    // cell's row mounted, the one tab stop, so make another cell the active one first.)
    await cell(g, 5, 2).click();
    await scrollTo(g, 20_000);
    await expect(rowCheckbox(g, "ORD-00001")).toHaveCount(0);
    await expect(summary(page)).toHaveText(`1 of ${ROWS} row(s) selected.`);
    // Back: the same row is checked again.
    await scrollTo(g, 0);
    await expect(rowCheckbox(g, "ORD-00001")).toHaveAttribute("aria-checked", "true");

    // Through a sort: id descending puts ORD-00001 last; the selection followed it.
    await sortButton(g, 1).click();
    await expect(cell(g, "header", 1)).toHaveAttribute("aria-sort", "descending");
    await expect(cell(g, 0, 1)).toHaveText(orderId(ROWS - 1));
    await scrollTo(g, "end");
    await expect(rowCheckbox(g, "ORD-00001")).toHaveAttribute("aria-checked", "true");
    await expect(g.locator('[role="row"][data-state="selected"]')).toHaveCount(1);
  });

  test("the header checkbox selects every row that passes the filter", async ({ page }) => {
    await gotoHydrated(page, PAGE_URL);
    const g = grid(page);
    await expect(cell(g, 0, 1)).toHaveText("ORD-00001");
    const refunded = Array.from({ length: ROWS }, (_, i) => i).filter((i) => status(i) === "Refunded").length;

    await filter(page).fill("refunded");
    await expect(g).toHaveAttribute("aria-rowcount", String(refunded + 1));
    await cell(g, "header", 0).getByRole("checkbox").click();
    await expect(summary(page)).toHaveText(`${refunded} of ${refunded} row(s) selected.`);
    await expect(cell(g, "header", 0).getByRole("checkbox")).toHaveAttribute("aria-checked", "true");

    // The filter hides rows, it does not forget them: clearing it, every selected row is still selected.
    await filter(page).fill("");
    await expect(summary(page)).toHaveText(`${refunded} of ${ROWS} row(s) selected.`);
    await expect(cell(g, "header", 0).getByRole("checkbox")).toHaveAttribute("aria-checked", "mixed");
  });
});

test.describe("Table and Grid layouts share one table look", () => {
  // The paged table of the `main` demo and the Grid of the `large` one, each with its first row selected: the
  // values the theme's `--dx-table-*` tokens decide must compute the same in both.
  const read = async (page: Page) => {
    const main = demoFrame(page);
    const table = main.locator('[data-slot="table"]');
    await expect(table.locator("tbody tr")).toHaveCount(5);
    await main.getByRole("checkbox", { name: /^Select row / }).first().click();
    const g = grid(page);
    await expect(cell(g, 0, 1)).toHaveText("ORD-00001");
    await rowCheckbox(g, "ORD-00001").click();
    await expect(g.locator('[role="row"][data-state="selected"]')).toHaveCount(1);
    await page.mouse.move(0, 0); // off the rows: a hovered row paints the hover fill, not the selected one
    await page.waitForTimeout(400); // the Table row's background transition
    const style = (el: Element, props: string[]) => {
      const cs = getComputedStyle(el);
      return Object.fromEntries(props.map((p) => [p, cs.getPropertyValue(p)]));
    };
    const tableLook = await table.evaluate((root, fn) => {
      const f = new Function("el", "props", `return (${fn})(el, props)`) as (el: Element, p: string[]) => Record<string, string>;
      const row = root.querySelector("tbody tr")!;
      const body = row.querySelector("td:nth-child(3)")!;
      const head = root.querySelector("thead th:nth-child(3)")!;
      const plainRow = root.querySelector("tbody tr:nth-child(2)")!;
      return {
        table: f(root, ["font-size"]),
        cell: f(body, ["padding-left", "padding-right", "font-size"]),
        head: f(head, ["font-weight", "padding-left"]),
        selectedRow: f(row, ["background-color"]),
        plainRow: f(plainRow, ["background-color", "border-bottom-width", "border-bottom-style", "border-bottom-color"]),
        rowHeight: String(Math.round(row.getBoundingClientRect().height)),
        headHeight: String(Math.round(head.getBoundingClientRect().height)),
      };
    }, style.toString());
    const gridLook = await g.evaluate((root, fn) => {
      const f = new Function("el", "props", `return (${fn})(el, props)`) as (el: Element, p: string[]) => Record<string, string>;
      const selected = root.querySelector('[role="row"][data-state="selected"]')!;
      const body = root.querySelector('[data-grid-cell="0:1"]')!;
      const head = root.querySelector('[data-grid-cell="header:1"]')!;
      const plainRow = root.querySelector('[role="row"][aria-rowindex="3"]')!;
      const plainCell = plainRow.querySelector('[data-grid-cell]:not([data-grid-pinned])')!;
      return {
        table: f(root, ["font-size"]),
        cell: f(body, ["padding-left", "padding-right", "font-size"]),
        head: f(head, ["font-weight", "padding-left"]),
        selectedRow: f(selected, ["background-color"]),
        plainRow: f(plainCell, ["background-color", "border-bottom-width", "border-bottom-style", "border-bottom-color"]),
        rowHeight: String(Math.round(selected.getBoundingClientRect().height)),
        headHeight: String(Math.round(head.getBoundingClientRect().height)),
      };
    }, style.toString());
    return { tableLook, gridLook };
  };

  test("text size, cell padding, header weight and height, row border, selected fill and row height match", async ({ page }) => {
    await gotoHydrated(page, PAGE_URL);
    const { tableLook, gridLook } = await read(page);
    expect(gridLook.table["font-size"]).toBe(tableLook.table["font-size"]);
    expect(gridLook.cell["padding-left"]).toBe(tableLook.cell["padding-left"]);
    expect(gridLook.cell["padding-right"]).toBe(tableLook.cell["padding-right"]);
    expect(gridLook.cell["font-size"]).toBe(tableLook.cell["font-size"]);
    expect(gridLook.head).toEqual(tableLook.head);
    expect(gridLook.headHeight).toBe(tableLook.headHeight);
    expect(gridLook.selectedRow["background-color"]).toBe(tableLook.selectedRow["background-color"]);
    expect(gridLook.plainRow["border-bottom-width"]).toBe(tableLook.plainRow["border-bottom-width"]);
    expect(gridLook.plainRow["border-bottom-style"]).toBe(tableLook.plainRow["border-bottom-style"]);
    expect(gridLook.plainRow["border-bottom-color"]).toBe(tableLook.plainRow["border-bottom-color"]);
    expect(gridLook.rowHeight).toBe(tableLook.rowHeight);
  });
});
